CREATE OR REPLACE FUNCTION public.set_deputy_self_service(_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_leitung(auth.uid()) THEN RAISE EXCEPTION 'Dazu fehlt dir die Berechtigung.'; END IF; IF _enabled IS NULL THEN RAISE EXCEPTION 'Ungültige Einstellung.'; END IF; INSERT INTO public.app_settings(key,value,is_public,updated_by) VALUES('deputy_self_service',to_jsonb(_enabled),false,auth.uid()) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,is_public=false,updated_by=auth.uid(),updated_at=now(); END $$; REVOKE ALL ON FUNCTION public.set_deputy_self_service(boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.set_deputy_self_service(boolean) TO authenticated;